//! `src/base_names.rs` is generated by `scripts/bend-base-names.sh` from the pinned clone (Q-BD3). This test runs the script and fails when the committed
//! file is not what it prints: the grammar pin moved, or `base.bend` changed, and the file was not regenerated. Ignored by default (needs the clone).
//!
//!     BEND_CLONE=../language_clone/bend cargo test -p bend-analysis --test base_names -- --ignored
//!
//! Regenerate with `scripts/bend-base-names.sh <clone> --write`.

use std::fs;
use std::path::{Path, PathBuf};
use std::process::Command;

#[test]
#[ignore = "needs BEND_CLONE and bash"]
fn base_names_are_current() {
    let repo: PathBuf = Path::new(env!("CARGO_MANIFEST_DIR")).join("../../../..");
    let clone = repo.join(std::env::var_os("BEND_CLONE").expect("BEND_CLONE names the bend clone"));
    let out = Command::new("bash")
        .arg(repo.join("scripts/bend-base-names.sh"))
        .arg(&clone)
        .output()
        .expect("bash runs the script");
    assert!(
        out.status.success(),
        "the script failed: {}",
        String::from_utf8_lossy(&out.stderr)
    );
    let generated = String::from_utf8(out.stdout).expect("the script prints UTF-8");
    let committed =
        fs::read_to_string(Path::new(env!("CARGO_MANIFEST_DIR")).join("src/base_names.rs"))
            .expect("src/base_names.rs");
    assert!(
        generated == committed,
        "src/base_names.rs is stale: run scripts/bend-base-names.sh {} --write",
        clone.display()
    );
}
